mapper.insert:

    SELECT
        'CICO'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(CITY_CODE_NO), LENGTH('CICO' ) + 1)), 0) + 1, 6, '0')
    FROM CITY_CODE

	INSERT INTO CITY_CODE (
	CITY_CODE_NO
	,CITY_NAME
	) VALUES (
	#{cityCodeNo}
	,#{cityName}
	)

mapper.update:
UPDATE CITY_CODE
SET
CITY_NAME = #{cityName}
WHERE
